var app=angular.module("kycPartnershipApp",[]);app.service("kycPartnershipService",["$http",function($http){var protocal=window.location.protocol;var host=window.location.host;var uRl=protocal+"//"+host+"/";this.save=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.post(uRl+"kyc-partnership/save",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})};this.getAllKYCRecords=function(){return $http.get(uRl+"kyc-partnership/getAllKycRecord")};this.getAllBranchListOfCOPs=function(userName){return $http.get(uRl+"kyc-partnership/getAllBranchListOfCOPs/"+userName)};this.getAllBranchListOfBOM=function(userName){return $http.get(uRl+"kyc-partnership/getAllBranchListOfBOM/"+userName)};this.get=function(id){return $http.get(uRl+"kyc-partnership/get/"+id)};this.delete=function(id){return $http.delete(uRl+"kyc-partnership/delete/"+id)};this.getJsonFile=function(){return $http.get(uRl+"kyc-partnership/getJsonFile")};this.getAadhar=function(adharNo){return $http.get(uRl+"kyc-partnership/getAadhar/"+adharNo)};this.getRecordByCode=function(code){return $http.get(uRl+"kyc-partnership/getRecordByCode/"+code)};this.update=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.put(uRl+"kyc-partnership/update",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})};this.updateCOPs=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.put(uRl+"kyc-partnership/updateCOPs",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})}}]);